oficial('examen_completos', {"exam_name": {"$in": [2024, "2024"]}, "question": {"$in": ["Dentro del proceso asistencial descrito en la Vía Clínica de Recuperación Intensificada de Cirugía del Adulto (2020), ¿qué actividad se considera desactualizada durante el preoperatorio?:", "Dentro del proceso asistencial descrito en la Vía Clínica de Recuperación intensificada de Cirugía del Adulto (2020), ¿qué actividad se considera desactualizada durante el preoperatorio?:"]}}, {"question": "Dentro del proceso asistencial descrito en la Vía Clínica de Recuperación intensificada de Cirugía del Adulto (2020), ¿qué actividad se considera desactualizada durante el preoperatorio?:"}, "2024 fila 2643 (oficial 178)", false);
